sys_ui_page.client_script:
// =============================================================================
// Incident Agent Cockpit — UI Page client script.
// Vanilla JS, no jQuery. Mirrors the existing Flight Deck conventions.
// =============================================================================

var IAC = {
    scope: 'mine',
    sort: 'urgency',
    filters: {
        priority: [],
        state: [],
        has_blockers: false,
        awaiting: false
    },
    rows: [],
    selectedSysId: '',
    checkedSysIds: {},
    refreshTimer: null,
    refreshIntervalMs: 60000
};

function acById(id) {
    return document.getElementById(id);
}

function acEscape(value) {
    if (value === null || value === undefined)
        return '';
    return String(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function acShowMessage(type, text) {
    var el = acById('ac-message');
    if (!el) return;
    el.className = 'ac-message ' + type;
    el.style.display = 'block';
    el.textContent = text || '';
}

function acClearMessage() {
    var el = acById('ac-message');
    if (!el) return;
    el.className = 'ac-message';
    el.style.display = 'none';
    el.textContent = '';
}

function acPriorityClass(text) {
    var p = String(text || '');
    if (p.indexOf('1') === 0) return 'ac-badge ac-badge-priority-1';
    if (p.indexOf('2') === 0) return 'ac-badge ac-badge-priority-2';
    if (p.indexOf('3') === 0) return 'ac-badge ac-badge-priority-3';
    return 'ac-badge ac-badge-priority-4';
}

function acStateClass(text) {
    var s = String(text || '');
    if (s === 'New') return 'ac-badge ac-badge-state-new';
    if (s === 'In Progress') return 'ac-badge ac-badge-state-progress';
    if (s === 'On Hold') return 'ac-badge ac-badge-state-hold';
    if (s === 'Resolved') return 'ac-badge ac-badge-state-resolved';
    if (s === 'Closed') return 'ac-badge ac-badge-state-closed';
    return 'ac-badge ac-badge-neutral';
}

function acSlaClass(status) {
    if (status === 'bad') return 'ac-badge ac-badge-sla-bad';
    if (status === 'warn') return 'ac-badge ac-badge-sla-warn';
    if (status === 'ok') return 'ac-badge ac-badge-sla-ok';
    return 'ac-badge ac-badge-neutral';
}

function acClampPercent(n) {
    var v = parseInt(n, 10) || 0;
    if (v < 0) v = 0;
    if (v > 100) v = 100;
    return v;
}

function acFormatAge(minutes) {
    var m = parseInt(minutes, 10) || 0;
    if (m < 60) return m + 'm';
    if (m < 60 * 24) return Math.floor(m / 60) + 'h ' + (m % 60) + 'm';
    return Math.floor(m / (60 * 24)) + 'd ' + Math.floor((m % (60 * 24)) / 60) + 'h';
}

// =============================================================================
// AJAX wrapper — mirrors fdAjax pattern.
// =============================================================================

function acAjax(methodName, params, callback) {
    var ga = new GlideAjax('IncidentAgentCockpitAjax');
    ga.addParam('sysparm_name', methodName);

    if (params) {
        for (var key in params) {
            if (params.hasOwnProperty(key))
                ga.addParam('sysparm_' + key, params[key]);
        }
    }

    ga.getXMLAnswer(function(answer) {
        var payload = {};
        try {
            payload = JSON.parse(answer || '{}');
        } catch (e) {
            acShowMessage('error', 'Could not parse server response: ' + e.message);
            return;
        }
        callback(payload || {});
    });
}

// =============================================================================
// Queue load + render
// =============================================================================

function acLoadQueue(silent) {
    if (!silent)
        acShowMessage('info', 'Loading queue...');

    acAjax('loadQueue', {
        scope: IAC.scope,
        sort: IAC.sort,
        filters: JSON.stringify(IAC.filters)
    }, function(payload) {
        if (!payload || !payload.ok) {
            acShowMessage('error', (payload && payload.message) || 'Could not load queue.');
            return;
        }

        IAC.rows = payload.rows || [];
        acRenderHeader(payload);
        acRenderPulse(payload.pulse || {});
        acRenderStrip(IAC.rows);
        acRenderShiftPulse(payload, IAC.rows);
        acClearMessage();
    });
}

function acRenderHeader(payload) {
    var name = (payload.user || {}).name || 'agent';
    acById('ac-greeting').textContent = 'Cockpit — ' + name;
    acById('ac-subline').textContent = 'Showing ' + (payload.rows || []).length + ' incidents · scope: ' + acScopeLabel(payload.scope) + ' · loaded ' + (payload.shift_started || '');

    var btns = document.querySelectorAll('.ac-scope-btn');
    var i;
    for (i = 0; i < btns.length; i++) {
        if (btns[i].getAttribute('data-scope') === IAC.scope)
            btns[i].classList.add('active');
        else
            btns[i].classList.remove('active');
    }
}

function acScopeLabel(s) {
    if (s === 'group') return 'My group';
    if (s === 'watch') return 'Watchlist';
    return 'My incidents';
}

function acRenderPulse(pulse) {
    acById('ac-pulse-total').textContent = pulse.total || 0;
    acById('ac-pulse-at-risk').textContent = pulse.at_risk || 0;
    acById('ac-pulse-awaiting').textContent = pulse.awaiting_customer || 0;
    acById('ac-pulse-sla').textContent = pulse.sla_breach || 0;
    acById('ac-pulse-stale').textContent = pulse.stale || 0;
}

function acRenderStrip(rows) {
    var host = acById('ac-strip');
    if (!host) return;

    if (!rows.length) {
        host.innerHTML = '<div class="ac-empty">No incidents match the current scope and filters.</div>';
        return;
    }

    var html = [];
    var i;
    for (i = 0; i < rows.length; i++)
        html.push(acRowHtml(rows[i]));

    host.innerHTML = html.join('');
}

function acRowHtml(row) {
    var checked = IAC.checkedSysIds[row.sys_id] ? ' checked="checked"' : '';
    var selectedCls = (IAC.selectedSysId === row.sys_id) ? ' selected' : '';
    var scores = row.lite_scores || {};
    var chip = row.next_action_chip || { label: '', tone: 'neutral' };

    return '' +
        '<div class="ac-row' + selectedCls + '" data-sys-id="' + acEscape(row.sys_id) + '">' +
            '<input type="checkbox" class="ac-row-check" data-row-check="' + acEscape(row.sys_id) + '"' + checked + ' />' +
            '<div class="ac-row-id">' +
                '<span class="ac-row-number">' + acEscape(row.number) + '</span>' +
                '<div class="ac-row-badges">' +
                    '<span class="' + acPriorityClass(row.priority) + '">' + acEscape(row.priority || 'P?') + '</span>' +
                    '<span class="' + acStateClass(row.state) + '">' + acEscape(row.state || '—') + '</span>' +
                '</div>' +
            '</div>' +
            '<div class="ac-row-title" title="' + acEscape(row.short_description) + '">' + acEscape(row.short_description || '(no short description)') + '</div>' +
            '<div class="ac-row-bars">' +
                acBar('readiness', scores.readiness) +
                acBar('risk', scores.risk) +
                acBar('dup', scores.dup) +
                acBar('escalation', scores.escalation) +
            '</div>' +
            '<div class="ac-row-meta">' +
                '<span class="ac-chip ac-chip-tone-' + acEscape(chip.tone) + '" style="cursor:default;">' + acEscape(chip.label || '—') + '</span>' +
                '<span class="' + acSlaClass((row.sla || {}).status) + '">' + acEscape((row.sla || {}).label || 'No SLA') + '</span>' +
                '<span>Activity: <strong>' + acFormatAge(row.last_activity_minutes) + '</strong> ago</span>' +
            '</div>' +
            '<div class="ac-row-actions">' +
                '<button class="ac-icon-btn" type="button" data-row-action="open" data-sys-id="' + acEscape(row.sys_id) + '">Flight Deck</button>' +
                '<button class="ac-icon-btn" type="button" data-row-action="quicknote" data-sys-id="' + acEscape(row.sys_id) + '">Note</button>' +
            '</div>' +
        '</div>';
}

function acBar(kind, value) {
    var pct = acClampPercent(value);
    return '<div class="ac-bar bar-' + kind + '" title="' + kind + ': ' + pct + '">' +
        '<div class="ac-bar-fill" style="width:' + pct + '%;"></div>' +
        '<div class="ac-bar-label">' + pct + '</div>' +
    '</div>';
}

function acRenderShiftPulse(payload, rows) {
    var stale = 0;
    var oldestStaleMin = 0;
    var i;
    for (i = 0; i < rows.length; i++) {
        if ((rows[i].last_activity_minutes || 0) >= 240) {
            stale++;
            if (rows[i].last_activity_minutes > oldestStaleMin)
                oldestStaleMin = rows[i].last_activity_minutes;
        }
    }
    var msg = rows.length + ' in queue · ' + stale + ' stale';
    if (oldestStaleMin > 0)
        msg += ' · oldest untouched: ' + acFormatAge(oldestStaleMin);
    acById('ac-shiftpulse').textContent = msg;
}

// =============================================================================
// Focus lane
// =============================================================================

function acSelectRow(sysId) {
    IAC.selectedSysId = sysId;

    var rows = document.querySelectorAll('.ac-row');
    var i;
    for (i = 0; i < rows.length; i++) {
        if (rows[i].getAttribute('data-sys-id') === sysId)
            rows[i].classList.add('selected');
        else
            rows[i].classList.remove('selected');
    }

    acAjax('getFocus', { sys_id: sysId }, function(payload) {
        if (!payload || !payload.ok) {
            acRenderFocusEmpty((payload && payload.message) || 'Could not load incident.');
            return;
        }
        acRenderFocus(payload);
    });
}

function acRenderFocusEmpty(msg) {
    var host = acById('ac-focus');
    host.innerHTML = '<div class="ac-focus-empty"><strong>' + acEscape(msg || 'No incident selected.') + '</strong></div>';
}

function acRenderFocus(p) {
    var host = acById('ac-focus');
    var summary = p.summary || {};
    var metrics = p.metrics || {};
    var nba = p.next_action || {};
    var fixCards = p.fix_cards || [];
    var sla = p.sla || {};
    var lj = p.last_journal || {};

    var html = '';
    html += '<h3 class="ac-focus-title">' + acEscape(p.number || 'Incident') + '</h3>';
    html += '<div class="ac-focus-subtitle">' + acEscape(p.short_description || '') + '</div>';

    html += '<div class="ac-hero-actions" style="display:flex; gap:6px; margin-bottom:6px;">';
    html += '<button class="ac-btn secondary" type="button" data-row-action="open" data-sys-id="' + acEscape(p.sys_id) + '">Open in Flight Deck</button>';
    html += '</div>';

    html += '<div class="ac-focus-section"><h4>Snapshot</h4><div class="ac-kv-grid">';
    html += acKv('Caller', summary.caller);
    html += acKv('Group', summary.assignment_group);
    html += acKv('Assigned to', summary.assigned_to);
    html += acKv('CI', summary.ci);
    html += acKv('Category', summary.category);
    html += acKv('Impact / Urgency', (summary.impact || '—') + ' / ' + (summary.urgency || '—'));
    html += '</div></div>';

    if (sla && sla.label) {
        html += '<div class="ac-focus-section"><h4>SLA</h4>';
        html += '<span class="' + acSlaClass(sla.status) + '">' + acEscape(sla.label) + '</span>';
        if (sla.detail)
            html += '<div class="ac-kv-value" style="margin-top:6px;">' + acEscape(sla.detail) + '</div>';
        html += '</div>';
    }

    if (nba && nba.title) {
        html += '<div class="ac-focus-section"><h4>Next best action</h4>';
        html += '<div class="ac-kv-value"><strong>' + acEscape(nba.title) + '</strong></div>';
        if (nba.rationale)
            html += '<div class="ac-fix-detail">' + acEscape(nba.rationale) + '</div>';
        html += '</div>';
    }

    if (fixCards.length) {
        html += '<div class="ac-focus-section"><h4>Top fix cards</h4>';
        var i;
        for (i = 0; i < fixCards.length; i++) {
            var fc = fixCards[i] || {};
            var tone = fc.severity || fc.tone || 'info';
            html += '<div class="ac-fix-card tone-' + acEscape(tone) + '">';
            html += '<div class="ac-fix-title">' + acEscape(fc.title || fc.label || 'Action') + '</div>';
            if (fc.detail || fc.description)
                html += '<div class="ac-fix-detail">' + acEscape(fc.detail || fc.description) + '</div>';
            html += '</div>';
        }
        html += '</div>';
    }

    if (metrics && (metrics.readiness || metrics.reopen_risk || metrics.duplicate_confidence || metrics.escalation_probability)) {
        html += '<div class="ac-focus-section"><h4>Metrics</h4><div class="ac-kv-grid">';
        html += acKv('Readiness', acMetricVal(metrics.readiness));
        html += acKv('Reopen risk', acMetricVal(metrics.reopen_risk));
        html += acKv('Duplicate', acMetricVal(metrics.duplicate_confidence));
        html += acKv('Escalation', acMetricVal(metrics.escalation_probability));
        html += '</div></div>';
    }

    if (lj && lj.text) {
        html += '<div class="ac-focus-section"><h4>Last journal entry</h4>';
        html += '<div class="ac-kv-label">' + acEscape(lj.author || '') + ' · ' + acEscape(lj.when || '') + '</div>';
        html += '<div class="ac-kv-value" style="white-space:pre-wrap;">' + acEscape(lj.text) + '</div>';
        html += '</div>';
    }

    html += '<div class="ac-focus-section"><h4>Quick work note</h4>';
    html += '<div class="ac-quick-form">';
    html += '<textarea id="ac-focus-note" placeholder="Add a quick work note..."></textarea>';
    html += '<button class="ac-btn" type="button" id="ac-focus-note-btn" data-sys-id="' + acEscape(p.sys_id) + '">Save note</button>';
    html += '</div></div>';

    host.innerHTML = html;

    var btn = acById('ac-focus-note-btn');
    if (btn) {
        btn.onclick = function() {
            var ta = acById('ac-focus-note');
            var note = (ta && ta.value) || '';
            if (!note) {
                acShowMessage('error', 'Note cannot be empty.');
                return;
            }
            acAjax('quickUpdate', { sys_id: p.sys_id, note: note }, function(resp) {
                if (resp && resp.ok) {
                    acShowMessage('success', 'Work note added to ' + p.number + '.');
                    if (ta) ta.value = '';
                } else {
                    acShowMessage('error', (resp && resp.message) || 'Could not save note.');
                }
            });
        };
    }
}

function acMetricVal(m) {
    if (!m) return '—';
    if (typeof m === 'object' && m !== null) {
        if (typeof m.value !== 'undefined') return m.value + (m.unit || '');
        if (typeof m.percent !== 'undefined') return m.percent + '%';
    }
    return String(m);
}

function acKv(label, value) {
    return '<div><div class="ac-kv-label">' + acEscape(label) + '</div><div class="ac-kv-value">' + acEscape(value || '—') + '</div></div>';
}

// =============================================================================
// Bulk tray
// =============================================================================

function acRefreshBulkTray() {
    var ids = acCheckedIds();
    var tray = acById('ac-bulk');
    var count = acById('ac-bulk-count');
    if (!tray || !count) return;

    if (ids.length) {
        tray.style.display = 'flex';
        count.textContent = ids.length + ' selected';
        acPauseAutoRefresh();
    } else {
        tray.style.display = 'none';
        acResumeAutoRefresh();
    }
}

function acCheckedIds() {
    var out = [];
    var k;
    for (k in IAC.checkedSysIds) {
        if (IAC.checkedSysIds.hasOwnProperty(k) && IAC.checkedSysIds[k])
            out.push(k);
    }
    return out;
}

function acClearChecks() {
    IAC.checkedSysIds = {};
    var boxes = document.querySelectorAll('.ac-row-check');
    var i;
    for (i = 0; i < boxes.length; i++)
        boxes[i].checked = false;
    acRefreshBulkTray();
}

function acBulk(method, params, successMsg) {
    var ids = acCheckedIds();
    if (!ids.length) {
        acShowMessage('error', 'No incidents selected.');
        return;
    }
    var p = { sys_ids: ids.join(',') };
    var k;
    for (k in (params || {})) {
        if (params.hasOwnProperty(k))
            p[k] = params[k];
    }
    acShowMessage('info', 'Applying bulk action...');
    acAjax(method, p, function(resp) {
        if (!resp) {
            acShowMessage('error', 'Bulk action failed.');
            return;
        }
        if (resp.ok)
            acShowMessage('success', (successMsg || 'Bulk action applied.') + ' ' + (resp.message || ''));
        else
            acShowMessage('error', resp.message || 'Bulk action failed.');
        acClearChecks();
        acLoadQueue(true);
    });
}

// =============================================================================
// Filters
// =============================================================================

function acToggleFilterArr(arr, value) {
    var i = arr.indexOf(value);
    if (i >= 0) arr.splice(i, 1);
    else arr.push(value);
    return arr;
}

function acReflectFilterChips() {
    var chips = document.querySelectorAll('.ac-chip');
    var i;
    for (i = 0; i < chips.length; i++) {
        var chip = chips[i];
        var pri = chip.getAttribute('data-filter-priority');
        var st = chip.getAttribute('data-filter-state');
        var fl = chip.getAttribute('data-filter-flag');
        var active = false;
        if (pri && IAC.filters.priority.indexOf(pri) >= 0) active = true;
        if (st && IAC.filters.state.indexOf(st) >= 0) active = true;
        if (fl === 'has_blockers' && IAC.filters.has_blockers) active = true;
        if (fl === 'awaiting' && IAC.filters.awaiting) active = true;
        if (active) chip.classList.add('active');
        else chip.classList.remove('active');
    }
}

function acClearFilters() {
    IAC.filters = { priority: [], state: [], has_blockers: false, awaiting: false };
    acReflectFilterChips();
    acLoadQueue();
}

// =============================================================================
// Auto-refresh
// =============================================================================

function acStartAutoRefresh() {
    acStopAutoRefresh();
    IAC.refreshTimer = setInterval(function() {
        if (IAC.selectedSysId) return;          // pause if a row is open in focus
        if (acCheckedIds().length) return;      // pause if bulk tray is open
        acLoadQueue(true);
    }, IAC.refreshIntervalMs);
}

function acStopAutoRefresh() {
    if (IAC.refreshTimer) {
        clearInterval(IAC.refreshTimer);
        IAC.refreshTimer = null;
    }
}

function acPauseAutoRefresh() { /* keep timer alive but the guards in acStartAutoRefresh skip ticks */ }
function acResumeAutoRefresh() { /* same — no-op; here for readability */ }

// =============================================================================
// Event delegation
// =============================================================================

function acHandleClick(evt) {
    var node = evt.target || evt.srcElement;
    var rowAction = '';
    var scope = '';
    var pulse = '';
    var rowSysId = '';

    // Let the change handler deal with checkbox clicks — don't open focus lane.
    if (node && (node.tagName === 'INPUT' || node.tagName === 'TEXTAREA' || node.tagName === 'SELECT'))
        return;

    while (node && node !== document) {
        if (node.getAttribute) {
            rowAction = node.getAttribute('data-row-action');
            scope = node.getAttribute('data-scope');
            pulse = node.getAttribute('data-pulse');
            if (!rowSysId)
                rowSysId = node.getAttribute('data-sys-id');
        }
        if (rowAction || scope || pulse) break;
        node = node.parentNode;
    }

    // Scope toggle
    if (scope) {
        evt.preventDefault();
        IAC.scope = scope;
        IAC.selectedSysId = '';
        acRenderFocusEmpty('No incident selected.');
        acClearChecks();
        acLoadQueue();
        return;
    }

    // Pulse-tile filter shortcuts
    if (pulse) {
        evt.preventDefault();
        if (pulse === 'sla_breach') { IAC.filters = { priority: [], state: [], has_blockers: false, awaiting: false }; }
        else if (pulse === 'awaiting_customer') { IAC.filters.awaiting = true; }
        else if (pulse === 'at_risk') { IAC.sort = 'urgency'; var ss = acById('ac-sort-select'); if (ss) ss.value = 'urgency'; }
        else if (pulse === 'stale') { IAC.sort = 'last_activity'; var ss2 = acById('ac-sort-select'); if (ss2) ss2.value = 'last_activity'; }
        acReflectFilterChips();
        acLoadQueue();
        return;
    }

    // Per-row actions
    if (rowAction === 'open' && rowSysId) {
        evt.preventDefault();
        window.open('incident_flight_deck.do?incident_sys_id=' + encodeURIComponent(rowSysId), '_blank');
        return;
    }

    if (rowAction === 'quicknote' && rowSysId) {
        evt.preventDefault();
        var note = window.prompt('Quick work note for selected incident:');
        if (note) {
            acAjax('quickUpdate', { sys_id: rowSysId, note: note }, function(resp) {
                if (resp && resp.ok)
                    acShowMessage('success', 'Work note added.');
                else
                    acShowMessage('error', (resp && resp.message) || 'Could not save note.');
            });
        }
        return;
    }

    // Filter chip
    var chipNode = evt.target || evt.srcElement;
    while (chipNode && chipNode !== document) {
        if (chipNode.classList && chipNode.classList.contains('ac-chip')) break;
        chipNode = chipNode.parentNode;
    }
    if (chipNode && chipNode !== document && chipNode.classList && chipNode.classList.contains('ac-chip')) {
        if (chipNode.id === 'ac-clear-filters') {
            acClearFilters();
            return;
        }
        var pri = chipNode.getAttribute('data-filter-priority');
        var st = chipNode.getAttribute('data-filter-state');
        var fl = chipNode.getAttribute('data-filter-flag');
        if (pri) acToggleFilterArr(IAC.filters.priority, pri);
        if (st) acToggleFilterArr(IAC.filters.state, st);
        if (fl === 'has_blockers') IAC.filters.has_blockers = !IAC.filters.has_blockers;
        if (fl === 'awaiting') IAC.filters.awaiting = !IAC.filters.awaiting;
        acReflectFilterChips();
        acLoadQueue();
        return;
    }

    // Click on a row (not a button) -> select for focus lane
    var rowNode = evt.target || evt.srcElement;
    while (rowNode && rowNode !== document) {
        if (rowNode.classList && rowNode.classList.contains('ac-row')) break;
        rowNode = rowNode.parentNode;
    }
    if (rowNode && rowNode !== document && rowNode.classList && rowNode.classList.contains('ac-row')) {
        var sysId = rowNode.getAttribute('data-sys-id');
        if (sysId) acSelectRow(sysId);
    }
}

function acHandleChange(evt) {
    var t = evt.target || evt.srcElement;
    if (!t) return;

    if (t.id === 'ac-sort-select') {
        IAC.sort = t.value || 'urgency';
        acLoadQueue();
        return;
    }

    var rowCheck = t.getAttribute && t.getAttribute('data-row-check');
    if (rowCheck) {
        IAC.checkedSysIds[rowCheck] = !!t.checked;
        acRefreshBulkTray();
    }
}

function acBindEvents() {
    document.addEventListener('click', acHandleClick);
    document.addEventListener('change', acHandleChange);

    var refresh = acById('ac-refresh-btn');
    if (refresh) refresh.onclick = function() { acLoadQueue(); };

    var openFlight = acById('ac-open-flightdeck');
    if (openFlight) openFlight.onclick = function() {
        if (IAC.selectedSysId)
            window.open('incident_flight_deck.do?incident_sys_id=' + encodeURIComponent(IAC.selectedSysId), '_blank');
        else
            acShowMessage('info', 'Select an incident row first to open it in the Flight Deck.');
    };

    var ack = acById('ac-bulk-ack');
    if (ack) ack.onclick = function() {
        var note = (acById('ac-bulk-note') || {}).value || '';
        acBulk('bulkAck', { note: note }, 'Acknowledged.');
    };

    var transition = acById('ac-bulk-transition');
    if (transition) transition.onclick = function() {
        var state = (acById('ac-bulk-state') || {}).value || '';
        var note = (acById('ac-bulk-note') || {}).value || '';
        if (!state) {
            acShowMessage('error', 'Pick a transition target first.');
            return;
        }
        acBulk('bulkTransition', { state: state, note: note }, 'State updated.');
    };

    var reassign = acById('ac-bulk-reassign');
    if (reassign) reassign.onclick = function() {
        var group = (acById('ac-bulk-group') || {}).value || '';
        var note = (acById('ac-bulk-note') || {}).value || '';
        if (!group) {
            acShowMessage('error', 'Group sys_id is required for reassign.');
            return;
        }
        acBulk('bulkReassign', { group: group, note: note }, 'Reassigned.');
    };

    var cancel = acById('ac-bulk-cancel');
    if (cancel) cancel.onclick = function() { acClearChecks(); };
}

function initIncidentAgentCockpit() {
    var holder = acById('ac-initial-scope');
    IAC.scope = holder ? (holder.value || 'mine') : 'mine';

    acBindEvents();
    acReflectFilterChips();
    acLoadQueue();
    acStartAutoRefresh();
}

if (typeof addLoadEvent === 'function')
    addLoadEvent(initIncidentAgentCockpit);
else if (window.addEventListener)
    window.addEventListener('load', initIncidentAgentCockpit);
else
    window.onload = initIncidentAgentCockpit;
